/**
 * Ark wallet lifecycle (experimental, signet-only) on bark
 * (`@secondts/bark-react-native`): create / restore / open / back up /
 * remove one Ark wallet per device. Payments live in `arkPayments.ts`, coin
 * upkeep (refresh, move out, emergency exit) in `arkMaintenance.ts`.
 *
 * Key choice: the Ark wallet has its OWN BIP-39 mnemonic, generated by bark
 * (or restored by the user) and kept in SecureStore. It never reuses an
 * on-chain wallet's mnemonic:
 * - most on-chain wallets in the app are watch-only (xpub), so there is often
 *   no seed to reuse;
 * - the hot-wallet mnemonics hold mainnet funds, and this runs on signet —
 *   test software should never touch a real-money seed;
 * - two wallets driving one seed race on key indices and server-side state.
 * The Nostr nsec is not reused either: it is a messaging identity, may live
 * in a remote signer (Amber / NIP-46), and must stay rotatable.
 *
 * The native module is loaded lazily so a binary built without bark (or with
 * the flag off) never runs its install hooks.
 */
import * as SecureStore from 'expo-secure-store';
import AsyncStorage from '@react-native-async-storage/async-storage';
import {
  deleteAsync,
  documentDirectory,
  getInfoAsync,
  makeDirectoryAsync,
} from 'expo-file-system/legacy';
import type { OnchainWalletLike, WalletLike } from '@secondts/bark-react-native';
import { ARK_DEFAULT_SERVER, isArkEnabled, type ArkServerConfig } from './arkConfig';

export type BarkModule = typeof import('@secondts/bark-react-native');

export interface ArkHandle {
  bark: BarkModule;
  wallet: WalletLike;
  /** bark's own BDK wallet: funds boards, pays exit fees, receives offboards. */
  onchain: OnchainWalletLike;
  server: ArkServerConfig;
}

/** Same protection as the on-chain mnemonics in walletStorageService. */
const SECURE_OPTIONS: SecureStore.SecureStoreOptions = {
  keychainAccessible: SecureStore.AFTER_FIRST_UNLOCK_THIS_DEVICE_ONLY,
};

const mnemonicKey = (server: ArkServerConfig) => `ark_mnemonic_${server.network}_v1`;
const addressIndexKey = (server: ArkServerConfig) => `ark_receive_index_${server.network}_v1`;

export class ArkUnavailableError extends Error {
  constructor() {
    super('Ark is not available in this build');
    this.name = 'ArkUnavailableError';
  }
}

export class ArkNoWalletError extends Error {
  constructor() {
    super('No Ark wallet on this phone yet');
    this.name = 'ArkNoWalletError';
  }
}

export class ArkInvalidMnemonicError extends Error {
  constructor() {
    super('Not a valid recovery phrase');
    this.name = 'ArkInvalidMnemonicError';
  }
}

let barkModule: BarkModule | null | undefined;
let handlePromise: Promise<ArkHandle> | null = null;

/**
 * Load the bark native module, or null when this binary does not link it.
 * The package installs its Rust crate at import time, so it must only be
 * required once Ark is switched on.
 */
export function loadBark(): BarkModule | null {
  if (barkModule !== undefined) return barkModule;
  try {
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    barkModule = require('@secondts/bark-react-native') as BarkModule;
  } catch {
    barkModule = null;
  }
  return barkModule;
}

/** True when the flag is on AND the native module is linked in this binary. */
export function isArkAvailable(): boolean {
  return isArkEnabled() && loadBark() !== null;
}

function requireBark(): BarkModule {
  const bark = isArkEnabled() ? loadBark() : null;
  if (!bark) throw new ArkUnavailableError();
  return bark;
}

/** Trim, lower-case and single-space a typed recovery phrase. */
export function normaliseMnemonic(phrase: string): string {
  return phrase.trim().toLowerCase().split(/\s+/).join(' ');
}

/** True when this phone already holds an Ark wallet for the server's network. */
export async function hasArkWallet(server: ArkServerConfig = ARK_DEFAULT_SERVER): Promise<boolean> {
  return (await SecureStore.getItemAsync(mnemonicKey(server))) !== null;
}

function datadirUri(server: ArkServerConfig): string {
  if (!documentDirectory) throw new Error('No documents directory for the Ark wallet');
  return `${documentDirectory}ark/${server.network}/`;
}

/** Per-network bark data directory under the app's documents folder (a plain path, no `file://`). */
export async function ensureArkDatadir(
  server: ArkServerConfig = ARK_DEFAULT_SERVER,
): Promise<string> {
  const uri = datadirUri(server);
  const info = await getInfoAsync(uri);
  if (!info.exists) await makeDirectoryAsync(uri, { intermediates: true });
  // bark wants a plain, decoded path (no `file://`, no %20).
  return decodeURIComponent(uri.startsWith('file://') ? uri.slice('file://'.length) : uri);
}

function toBarkNetwork(bark: BarkModule, network: ArkServerConfig['network']) {
  switch (network) {
    case 'signet':
      return bark.Network.Signet;
  }
}

async function openHandle(
  bark: BarkModule,
  server: ArkServerConfig,
  mnemonic: string,
  opts: { create: boolean; skipRecovery: boolean },
): Promise<ArkHandle> {
  const datadir = await ensureArkDatadir(server);
  const network = toBarkNetwork(bark, server.network);
  const config = bark.Config.create({
    serverAddress: server.arkUrl,
    esploraAddress: server.esploraUrl,
  });
  // Since bark 0.12 boards, exits and the daemon use the on-chain wallet
  // given at open time, so it is created up front.
  const onchain = await bark.OnchainWallet.default_(network, mnemonic, config, datadir);
  // The daemon keeps the wallet synced and runs bark's background
  // maintenance while the app is open; the screen also offers a manual refresh.
  const wallet = await bark.Wallet.open(network, mnemonic, config, {
    datadir,
    onchain,
    runDaemon: true,
    createIfNotExists: opts.create,
    createWithoutServer: false,
    skipRecovery: opts.skipRecovery,
  });
  return { bark, wallet, onchain, server };
}

function remember(promise: Promise<ArkHandle>): Promise<ArkHandle> {
  handlePromise = promise.catch((err: unknown) => {
    handlePromise = null; // let the next caller retry
    throw err;
  });
  return handlePromise;
}

/** Open (or reuse) this phone's Ark wallet. Concurrent callers share one open. */
export function getArkHandle(server: ArkServerConfig = ARK_DEFAULT_SERVER): Promise<ArkHandle> {
  if (handlePromise) return handlePromise;
  return remember(
    (async () => {
      const bark = requireBark();
      const mnemonic = await SecureStore.getItemAsync(mnemonicKey(server));
      if (!mnemonic) throw new ArkNoWalletError();
      return openHandle(bark, server, mnemonic, { create: true, skipRecovery: false });
    })(),
  );
}

async function wipeLocal(server: ArkServerConfig): Promise<void> {
  await SecureStore.deleteItemAsync(mnemonicKey(server)).catch(() => {});
  await AsyncStorage.removeItem(addressIndexKey(server)).catch(() => {});
  await deleteAsync(datadirUri(server), { idempotent: true }).catch(() => {});
}

async function setUp(
  server: ArkServerConfig,
  mnemonic: string,
  skipRecovery: boolean,
): Promise<ArkHandle> {
  const bark = requireBark();
  if (await hasArkWallet(server)) throw new Error('An Ark wallet already exists on this phone');
  await SecureStore.setItemAsync(mnemonicKey(server), mnemonic, SECURE_OPTIONS);
  return remember(
    openHandle(bark, server, mnemonic, { create: true, skipRecovery }).catch(
      async (err: unknown) => {
        await wipeLocal(server); // nothing half-made is left behind
        throw err;
      },
    ),
  );
}

/** Create a brand-new Ark wallet with a fresh recovery phrase. */
export async function createArkWallet(
  server: ArkServerConfig = ARK_DEFAULT_SERVER,
): Promise<ArkHandle> {
  const bark = requireBark();
  const mnemonic = bark.generateMnemonic();
  if (!bark.validateMnemonic(mnemonic)) throw new ArkInvalidMnemonicError();
  // A brand-new seed has nothing to recover, so skip the mailbox scan.
  return setUp(server, mnemonic, true);
}

/** Restore from a recovery phrase; bark scans the server mailbox for the wallet's coins. */
export async function restoreArkWallet(
  phrase: string,
  server: ArkServerConfig = ARK_DEFAULT_SERVER,
): Promise<ArkHandle> {
  const bark = requireBark();
  const mnemonic = normaliseMnemonic(phrase);
  if (!bark.validateMnemonic(mnemonic)) throw new ArkInvalidMnemonicError();
  return setUp(server, mnemonic, false);
}

/**
 * The recovery phrase, for the backup screen only. Callers must gate this
 * behind device authentication and never log, toast or persist the result.
 */
export async function readArkMnemonicForBackup(
  server: ArkServerConfig = ARK_DEFAULT_SERVER,
): Promise<string | null> {
  return SecureStore.getItemAsync(mnemonicKey(server));
}

/** Stop the daemon and delete the wallet, its phrase and its data from this phone. */
export async function removeArkWallet(server: ArkServerConfig = ARK_DEFAULT_SERVER): Promise<void> {
  const open = handlePromise;
  handlePromise = null;
  if (open) {
    try {
      const handle = await open;
      await handle.wallet.stopDaemonWait();
    } catch {
      // Not open, or already stopped: nothing to stop.
    }
  }
  await wipeLocal(server);
}

/**
 * The address to show on the receive card. Ark addresses can be reused, so
 * keep showing the same one instead of deriving a new index on every screen
 * focus — each unused index widens the gap a seed recovery has to scan.
 */
export async function getArkReceiveAddress(
  wallet: WalletLike,
  server: ArkServerConfig = ARK_DEFAULT_SERVER,
): Promise<string> {
  const stored = await AsyncStorage.getItem(addressIndexKey(server)).catch(() => null);
  const index = stored === null ? NaN : Number(stored);
  if (Number.isInteger(index) && index >= 0) return wallet.peekAddress(index);
  const fresh = await wallet.newAddressWithIndex();
  await AsyncStorage.setItem(addressIndexKey(server), String(fresh.index)).catch(() => {});
  return fresh.address;
}

/** Test hook: forget the cached module and wallet. */
export function __resetArkForTests(): void {
  barkModule = undefined;
  handlePromise = null;
}
